    /// The open mode of a replica database. This parameter is only supported for Db2 DB instances and Oracle DB instances. Db2 Standby DB replicas are included in Db2 Advanced Edition (AE), Db2 Community Edition (CE), and Db2 Standard Edition (SE). The main use case for standby replicas is cross-Region disaster recovery. Because it doesn't accept user connections, a standby replica can't serve a read-only workload. You can create a combination of standby and read-only DB replicas for the same primary DB instance. For more information, see Working with replicas for Amazon RDS for Db2 in the Amazon RDS User Guide . To create standby DB replicas for RDS for Db2, set this parameter to mounted . Oracle Mounted DB replicas are included in Oracle Database Enterprise Edi- tion. The main use case for mounted replicas is cross-Region disas- ter recovery. The primary database doesn't use Active Data Guard to transmit information to the mounted replica. Because it doesn't ac- cept user connections, a mounted replica can't serve a read-only workload. You can create a combination of mounted and read-only DB replicas for the same primary DB instance. For more information, see Working with read replicas for Amazon RDS for Oracle in the Amazon RDS User Guide . For RDS Custom, you must specify this parameter and set it to mounted . The value won't be set by default. After replica creation, you can manage the open mode manually. Possible values: o open-read-only o mounted
    /// </summary>
    [CliOption("--replica-mode")]
    public AwsRdsModifyDbInstanceReplicaMode? ReplicaMode { get; set; }

    /// <summary>
    /// The automation mode of the RDS Custom DB instance. If full , the DB instance automates monitoring and instance recovery. If all paused , the instance pauses automation for the duration set by ResumeFullAu- tomationModeMinutes . Possible values: o full o all-paused
    /// </summary>
    [CliOption("--automation-mode")]
    public AwsRdsModifyDbInstanceAutomationMode? AutomationMode { get; set; }

    /// <summary>
    /// The number of minutes to pause the automation. When the time period ends, RDS Custom resumes full automation. Default: 60 Constraints: o Must be at least 60. o Must be no more than 1,440.
    /// </summary>
    [CliOption("--resume-full-automation-mode-minutes")]
    public int? ResumeFullAutomationModeMinutes { get; set; }

    [CliFlag("--enable-customer-owned-ip")]
    public bool? EnableCustomerOwnedIp { get; set; }

    /// <summary>
    /// The network type of the DB instance. The network type is determined by the DBSubnetGroup specified for the DB instance. A DBSubnetGroup can support only the IPv4 protocol or the IPv4 and the IPv6 protocols (DUAL ). For more information, see Working with a DB instance in a VPC in the Amazon RDS User Guide. Valid Values: IPV4 | DUAL
    /// </summary>
    [CliOption("--network-type")]
    public string? NetworkType { get; set; }

    /// <summary>
    /// The Amazon Resource Name (ARN) of the recovery point in Amazon Web Services Backup. This setting doesn't apply to RDS Custom DB instances. Constraints: o min: 43 o max: 350 o pattern: arn:aws[a-z-]*:backup:[-a-z0-9]+:[0-9]{12}:[-a-z]+:([a-z0-9\-]+:)?[a-z][a-z0-9\-]{0,255}
    /// </summary>
    [CliOption("--aws-backup-recovery-point-arn")]
    public string? AwsBackupRecoveryPointArn { get; set; }

    [CliFlag("--manage-master-user-password")]
    public bool? ManageMasterUserPassword { get; set; }

    [CliFlag("--rotate-master-user-password")]
    public bool? RotateMasterUserPassword { get; set; }

    /// <summary>
    /// The Amazon Web Services KMS key identifier to encrypt a secret that is automatically generated and managed in Amazon Web Services Se- crets Manager. This setting is valid only if both of the following conditions are met: o The DB instance doesn't manage the master user password in Amazon Web Services Secrets Manager. If the DB instance already manages the master user password in Amazon Web Services Secrets Manager, you can't change the KMS key used to encrypt the secret. o You are turning on ManageMasterUserPassword to manage the master user password in Amazon Web Services Secrets Manager. If you are turning on ManageMasterUserPassword and don't specify MasterUser- SecretKmsKeyId , then the aws/secretsmanager KMS key is used to encrypt the secret. If the secret is in a different Amazon Web Services account, then you can't use the aws/secretsmanager KMS key to encrypt the secret, and you must use a customer managed KMS key. The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key. To use a KMS key in a dif- ferent Amazon Web Services account, specify the key ARN or alias ARN. There is a default KMS key for your Amazon Web Services account. Your Amazon Web Services account has a different default KMS key for each Amazon Web Services Region.
    /// </summary>
    [SecretValue]
    [CliOption("--master-user-secret-kms-key-id")]
    public string? MasterUserSecretKmsKeyId { get; set; }

    [CliFlag("--multi-tenant")]
    public bool? MultiTenant { get; set; }

    [CliFlag("--dedicated-log-volume")]
    public bool? DedicatedLogVolume { get; set; }

    /// <summary>
    /// The target Oracle DB engine when you convert a non-CDB to a CDB. This intermediate step is necessary to upgrade an Oracle Database 19c non-CDB to an Oracle Database 21c CDB. Note the following requirements: o Make sure that you specify oracle-ee-cdb or oracle-se2-cdb . o Make sure that your DB engine runs Oracle Database 19c with an April 2021 or later RU. Note the following limitations: o You can't convert a CDB to a non-CDB. o You can't convert a replica database. o You can't convert a non-CDB to a CDB and upgrade the engine ver- sion in the same command. o You can't convert the existing custom parameter or option group when it has options or parameters that are permanent or persis- tent. In this situation, the DB instance reverts to the default option and parameter group. To avoid reverting to the default, specify a new parameter group with --db-parameter-group-name and a new option group with --option-group-name .
    /// </summary>
    [CliOption("--engine")]
    public string? Engine { get; set; }

    /// <summary>
    /// A list of additional storage volumes to modify or delete for the DB instance. You can create up to 3 additional storage volumes. Addi- tional storage volumes are supported for RDS for Oracle and RDS for SQL Server DB instances only. (structure) Contains details about the modification of an additional storage volume. VolumeName -&gt; (string) [required] The name of the additional storage volume that you want to modify. Valid Values: RDSDBDATA2 | RDSDBDATA3 | RDSDBDATA4 AllocatedStorage -&gt; (integer) The amount of storage allocated for the additional storage volume, in gibibytes (GiB). The minimum is 20 GiB. The maxi- mum is 65,536 GiB (64 TiB). IOPS -&gt; (integer) The number of I/O operations per second (IOPS) provisioned for the additional storage volume. This setting is only sup- ported for Provisioned IOPS SSD (io1 and io2 ) storage types. MaxAllocatedStorage -&gt; (integer) The upper limit in gibibytes (GiB) to which RDS can automati- cally scale the storage of the additional storage volume. You must provide a value greater than or equal to AllocatedStor- age . StorageThroughput -&gt; (integer) The storage throughput value for the additional storage vol- ume, in mebibytes per second (MiBps). This setting applies only to the General Purpose SSD (gp3 ) storage type. StorageType -&gt; (string) The new storage type for the additional storage volume. Valid Values: GP3 | IO2 SetForDelete -&gt; (boolean) Indicates whether to delete the additional storage volume. The value true schedules the volume for deletion. You can delete an additional storage volume only when it doesn't con- tain database files or other data. Shorthand Syntax: VolumeName=string,AllocatedStorage=integer,IOPS=integer,MaxAllocatedStorage=integer,StorageThroughput=integer,StorageType=string,SetForDelete=boolean ... JSON Syntax: [ { "VolumeName": "string", "AllocatedStorage": integer, "IOPS": integer, "MaxAllocatedStorage": integer, "StorageThroughput": integer, "StorageType": "string", "SetForDelete": true|false } ... ]
    /// </summary>
    [CliOption("--additional-storage-volumes")]
    public IEnumerable<string>? AdditionalStorageVolumes { get; set; }

    /// <summary>
    /// Tags to assign to resources associated with the DB instance. Valid Values: o auto-backup - The DB instance's automated backup. (structure) The tags to apply to resources when creating or modifying a DB instance or DB cluster. When you specify a tag, you must specify the resource type to tag, otherwise the request will fail. ResourceType -&gt; (string) The type of resource to tag on creation. Valid Values: o auto-backup - The DB instance's automated backup. o cluster-auto-backup - The DB cluster's automated backup. Tags -&gt; (list) A list of tags. For more information, see Tagging Amazon RDS resources in the Amazon RDS User Guide or Tagging Amazon Aurora and Amazon RDS resources in the Amazon Aurora User Guide . (structure) Metadata assigned to an Amazon RDS resource consisting of a key-value pair. For more information, see Tagging Amazon RDS resources in the Amazon RDS User Guide or Tagging Amazon Aurora and Amazon RDS resources in the Amazon Aurora User Guide . Key -&gt; (string) A key is the required name of the tag. The string value can be from 1 to 128 Unicode characters in length and can't be prefixed with aws: or rds: . The string can only contain only the set of Unicode let- ters, digits, white-space, '_', '.', ':', '/', '=', '+', '-', '@' (Java regex: "^([\p{L}\p{Z}\p{N}_.:/=+\-@]*)$"). Value -&gt; (string) A value is the optional value of the tag. The string value can be from 1 to 256 Unicode characters in length and can't be prefixed with aws: or rds: . The string can only contain only the set of Unicode let- ters, digits, white-space, '_', '.', ':', '/', '=', '+', '-', '@' (Java regex: "^([\p{L}\p{Z}\p{N}_.:/=+\-@]*)$"). Shorthand Syntax: ResourceType=string,Tags=[{Key=string,Value=string},{Key=string,Value=string}] ... JSON Syntax: [ { "ResourceType": "string", "Tags": [ { "Key": "string", "Value": "string" } ... ] } ... ]
    /// </summary>
    [CliOption("--tag-specifications")]
    public IEnumerable<string>? TagSpecifications { get; set; }

    /// <summary>
    /// Specifies the authentication type for the master user. With IAM mas- ter user authentication, you can change the master DB user to use IAM database authentication. You can specify one of the following values: o password - Use standard database authentication with a password. o iam-db-auth - Use IAM database authentication for the master user. This option is only valid for RDS for PostgreSQL and Aurora Post- greSQL engines. Possible values: o password o iam-db-auth
    /// </summary>
    [CliOption("--master-user-authentication-type")]
    public AwsRdsModifyDbInstanceMasterUserAuthenticationType? MasterUserAuthenticationType { get; set; }

    /// <summary>
    /// The lifecycle type for this DB instance. This setting applies only to RDS for MySQL and RDS for PostgreSQL. For Amazon Aurora DB instances, the engine lifecycle support is man- aged by the DB cluster. You can use this setting to enroll your DB instance into Amazon RDS Extended Support or to opt out. With RDS Extended Support, you can run the selected major engine version on your DB instance past the end of standard support for that engine version. For more informa- tion, see Amazon RDS Extended Support with Amazon RDS in the Amazon RDS User Guide . Valid Values: open-source-rds-extended-support | open-source-rds-ex- tended-support-disabled This setting doesn't apply to RDS Custom DB instances.
    /// </summary>
    [CliOption("--engine-lifecycle-support")]
    public string? EngineLifecycleSupport { get; set; }

    [CliFlag("--cli-input-json")]
    public bool? CliInputJson { get; set; }

    [CliFlag("--generate-cli-skeleton")]
    public bool? GenerateCliSkeleton { get; set; }

}
